import importlib
import os
import sys
from typing import Dict, Any, Type, List

# Represents the computational "gas" limit to enforce the $0.45 budget.
# In a real system, this would be a complex, multi-factor calculation.
# Here, it's a simple counter for operations.
GAS_LIMIT = 100

class GasMeter:
    """A simple meter for tracking computational cost."""
    def __init__(self, limit: int):
        self.limit = limit
        self.used = 0

    def consume(self, amount: int):
        """Consume gas. Raise an exception if the limit is exceeded."""
        if not isinstance(amount, int) or amount < 0:
            raise ValueError("Gas consumption amount must be a non-negative integer.")
        if self.used + amount > self.limit:
            raise MemoryError("Gas limit exceeded. Operation aborted.")
        self.used += amount

    def __repr__(self):
        return f"<GasMeter used={self.used}/{self.limit}>"

class Department:
    """Base class for all departments. Defines the interface."""
    def __init__(self, org_context: Dict[str, Any], gas_meter: GasMeter):
        self.org_context = org_context
        self.gas = gas_meter
        self.gas.consume(1) # Cost to instantiate a department

    def execute(self, data: Any) -> Any:
        """Main work function of the department."""
        raise NotImplementedError

class Orchestrator:
    """Loads and runs an Agent-Org."""
    def __init__(self, org_path: str):
        self.org_path = org_path
        self.departments: Dict[str, Type[Department]] = {}
        self.pipeline: List[str] = []
        self.load_org_definition()

    def load_org_definition(self):
        """
        Loads department modules and pipeline from the org's directory.
        This simulates loading an `agent-org.toml` and its associated code.
        """
        if not os.path.exists(self.org_path):
            raise FileNotFoundError(f"Org path not found: {self.org_path}")

        dept_dir = os.path.join(self.org_path, "depts")
        if not os.path.exists(dept_dir):
            raise FileNotFoundError(f"Departments directory not found: {dept_dir}")

        # Add org's depts directory to path for module loading
        sys.path.insert(0, dept_dir)

        # In a real system, this would parse a config file (e.g., agent-org.toml)
        # For this MVA, we use a simple convention.
        # This assumes all .py files in 'depts' are departments and ordered somehow.
        # For the MVA, we'll stick to the explicit pipeline for simplicity and determinism.
        self.pipeline = ["data_ingest", "processing", "output"]

        for dept_name in self.pipeline:
            try:
                module = importlib.import_module(dept_name) # Import directly from dept_dir
                # Assumes module contains a class named 'Dept' that inherits from Department
                dept_class = getattr(module, 'Dept')
                if not issubclass(dept_class, Department):
                    raise TypeError(f"Department '{dept_name}' must inherit from Department base class.")
                self.departments[dept_name] = dept_class
            except (ImportError, AttributeError) as e:
                raise RuntimeError(f"Failed to load department '{dept_name}': {e}")

        sys.path.pop(0) # Clean up sys.path

    def run(self, initial_data: Any) -> Dict[str, Any]:
        """Executes the agent-org's pipeline."""
        gas_meter = GasMeter(GAS_LIMIT)
        org_context = {'shared_state': {}, 'run_history': []}

        # Instantiate all departments
        active_depts = {}
        for name in self.pipeline:
            try:
                active_depts[name] = self.departments[name](org_context, gas_meter)
            except Exception as e:
                # Catch instantiation errors which might be due to gas limit or other issues
                raise RuntimeError(f"Failed to instantiate department '{name}': {e}")

        # Execute pipeline
        data = initial_data
        for dept_name in self.pipeline:
            gas_meter.consume(5) # Cost for orchestration and data passing
            dept = active_depts[dept_name]
            data = dept.execute(data)
            org_context['run_history'].append({'dept': dept_name, 'output': data})

        return {
            "final_result": data,
            "gas_used": gas_meter.used,
            "final_state": org_context['shared_state']
        }

