from agent_org.ork import Department, GAS_LIMIT

class Dept(Department):
    def execute(self, data_value):
        # Calculate gas needed to exceed limit.
        # org_buggy (without processing) uses 23 gas.
        # Orchestration for this dept is 5 gas.
        # So, 23 + 5 = 28 gas is already consumed before this dept's execute.
        # To exceed GAS_LIMIT (100), we need to consume 100 - 28 + 1 = 73 gas here.
        self.gas.consume(73)
        return {"value": data_value * 2 + 100, "expensive_repair": True}

