from agent_org.ork import Department

class Dept(Department):
    def execute(self, data):
        self.gas.consume(2)
        if 'value' not in data:
            raise ValueError("Input data must contain 'value'")
        self.org_context['shared_state']['ingested'] = True
        return data['value']
